/* Generated by test/build-classroom.js from the existing task views. */
(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current,state,course,palette='#537f65';const E=window.GameEngine,B=window.BoardRules;
const btn=(a,t,kind='',attrs='')=>`<button type="button" class="a-btn ${kind}" data-a="${a}" ${attrs}>${t}</button>`;
function scene(){return '<p>先看例子，再用自己的办法试一试。</p>';}
function numberVisual(t,s){if(t.visual==='fraction'){return t.fields.map((f,j)=>{const den=t.denominators?.[j]||t.denominator;return `<p>${esc(f.label)}：整体分${den}份，当前取${s.values[j]}份</p><div class="a-fraction" aria-label="同一整体的${den}等分">${Array.from({length:den},(_,i)=>`<span class="${i<s.values[j]?'on':''}"></span>`).join('')}</div>`;}).join('');}if(t.visual==='array'){const cols=Math.max(1,Math.min(10,s.values[t.arrayColumnsField??1]||1)),n=(s.values[0]||0)*(s.values[1]||0);return `<div class="a-units" style="--cols:${cols}" aria-label="${s.values[0]}组，每组${s.values[1]}个">${Array(n).fill('<span class="a-unit"></span>').join('')}</div>`;}if(t.visual==='rectangle'){return `<div class="a-units" style="--cols:${t.width}">${Array(t.width*t.height).fill('<span class="a-unit"></span>').join('')}</div><p class="a-muted">图上每格是一个单位，边界与内部格数分别观察。</p>`;}if(t.visual==='place')return `<div class="a-token-row">${Array(Math.min(9,s.values[0])).fill('<span class="a-pill">十</span>').join('')}${Array(Math.min(9,s.values[1])).fill('<span class="a-token"></span>').join('')}</div>`;if(t.rule==='linear')return `<div class="a-reading">总票数 = 人数 × 2 + 1<br>n = ${s.values[0]}；当前填写总数 ${s.values[1]}</div>`;return `<div class="a-token-row">${Array.from({length:s.values[0]||0},(_,i)=>`<span class="a-token ${i%2?'blue':''}"></span>`).join('')}</div>`;}
function activityBody(t,s){switch(t.kind){
 case 'choice':return `<div class="a-choice-grid">${t.options.map((o,i)=>`<button class="a-choice ${s.choice===i?'selected':''}" data-a="task" data-action="choose" data-v="${i}" aria-pressed="${s.choice===i}">${esc(o)}</button>`).join('')}</div>`;
 case 'number':return numberVisual(t,s)+t.fields.map((f,i)=>`<div class="a-number"><label>${esc(f.label)}</label><div class="a-controls">${btn('value','−','small',`data-i="${i}" data-d="-${f.step}" aria-label="减少${esc(f.label)}"`)}<output data-field="${i}">${s.values[i]}</output>${btn('value','＋','small',`data-i="${i}" data-d="${f.step}" aria-label="增加${esc(f.label)}"`)}</div></div>`).join('');
 case 'sort':return `<p class="a-muted">先选一张卡，再选它的类别。可以重新选择调整。</p>${t.cards.map((c,i)=>`<button class="a-sort-card ${s.selected===i?'selected':''}" data-a="task" data-action="select" data-v="${i}">${esc(c.label)}<small>${s.assign[i]!=null?'已放到：'+esc(t.categories[s.assign[i]]):'还未归类'}</small></button>`).join('')}<div class="a-choice-grid">${t.categories.map((c,i)=>`<button class="a-category" data-a="task" data-action="assign" data-v="${i}" ${s.selected==null?'disabled':''}>${esc(c)}</button>`).join('')}</div>`;
 case 'sequence':return `<p class="a-muted">用上下按钮重排，保留每一项，不漏掉关键步骤。</p>${s.order.map((n,i)=>`<div class="a-sequence"><strong>${i+1}</strong><span class="a-steptext">${esc(t.cards[n])}</span><div class="a-controls">${btn('order','↑','small',`data-i="${i}" data-d="-1" aria-label="第${i+1}项上移" ${i===0?'disabled':''}`)}${btn('order','↓','small',`data-i="${i}" data-d="1" aria-label="第${i+1}项下移" ${i===s.order.length-1?'disabled':''}`)}</div></div>`).join('')}`;
 case 'experiment':return `<p class="a-note">下方是给定示例／模拟模型，不是已经替你完成的真实实验。真实结果可以在记录里另写。</p><div class="a-controls">${t.trials.map((r,i)=>btn('task',esc(r.label)+(s.observed.includes(i)?' ✓':''),'small',`data-action="observe" data-v="${i}"`)).join('')}</div>${s.currentTrial!=null?labVisual(t,s.currentTrial):''}<table class="a-table"><thead><tr><th>情境</th><th>记录值</th><th>条件说明</th></tr></thead><tbody>${s.observed.map(i=>`<tr><td>${esc(t.trials[i].label)}</td><td>${t.trials[i].value}</td><td>${esc(t.trials[i].note)}</td></tr>`).join('')}</tbody></table><div class="a-choice-grid">${t.options.map((o,i)=>`<button class="a-choice ${s.choice===i?'selected':''}" data-a="task" data-action="choose" data-v="${i}">${esc(o)}</button>`).join('')}</div>`;
 case 'circuit':{const on=s.wires.every(Boolean)&&s.switchClosed;return `<p class="a-note">低压电路模型，不接家庭电源。</p><svg viewBox="0 0 500 300" role="img" aria-label="导线与开关闭合时灯亮的电路模型"><rect x="55" y="35" width="390" height="220" rx="18" fill="#f2f1e2"/>${[[90,75,410,75],[410,75,410,235],[90,235,410,235],[90,75,90,235]].map((v,i)=>`<path d="${i===1?'M410 75V155M410 200V235':`M${v[0]} ${v[1]}L${v[2]} ${v[3]}`}" stroke="${s.wires[i]?'#71927b':'#d8b299'}" stroke-width="9" stroke-dasharray="${s.wires[i]?'0':'12 14'}"/>`).join('')}<circle cx="250" cy="75" r="35" fill="${on?'#f3cf66':'#d3d8c8'}" stroke="#85977c" stroke-width="5"/><text x="250" y="82" text-anchor="middle" font-size="20">${on?'灯亮':'灯灭'}</text><rect x="205" y="213" width="90" height="45" rx="7" fill="#fff8db" stroke="#8c9a75" stroke-width="3"/><text x="250" y="242" text-anchor="middle" font-size="20">＋ 电池 −</text><path d="M410 155l${s.switchClosed?'0 45':'30 30'}" stroke="#b77e49" stroke-width="10"/></svg><div class="a-choice-grid">${['上方','右侧','下方','左侧'].map((l,i)=>btn('task',l+'导线 '+(s.wires[i]?'已连接':'有缺口'),'small',`data-action="wire" data-v="${i}"`)).join('')}</div>${btn('task',s.switchClosed?'断开开关':'闭合开关','primary','data-action="switch"')}`;}
 case 'studio':return `<ul class="a-prompts">${t.prompts.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>${t.mode!=='text'?`<div class="a-palette" aria-label="画笔颜色">${['#537f65','#d2a35d','#ba6f5b','#719aa8','#7b719d','#333e36','#ffffff'].map(c=>`<button class="a-color ${palette===c?'active':''}" style="background:${c}" data-a="color" data-color="${c}" aria-label="${c==='#ffffff'?'白色橡皮':'画笔 '+c}"></button>`).join('')}${btn('task','撤销一笔','small','data-action="undo"')}${btn('downloadArt','下载这张作品','small')}</div><p id="aCanvasLimit" class="a-muted" role="status">画板保留最多60笔，可随时下载PNG。</p><canvas class="a-canvas" id="aCanvas" width="640" height="480" aria-label="画板，可以用触屏或鼠标绘画"></canvas><p class="a-muted">也可用纸笔完成，再记录一句说明；不靠笔画数评分。</p>`:''}<label for="aText">作品说明／口述记录</label><textarea id="aText" maxlength="3000" placeholder="可以写，也可以由陪伴者记录一句。">${esc(s.text)}</textarea><div class="a-controls">${btn('task',s.reported?'已记录口述／动手 ✓':'我已口述／动手','small','data-action="reported"')}</div><p class="a-muted" id="aArtifactStatus">作品仅保存在这台设备，可在家长记录导出。</p>`;
 case 'route':return routeBoard(t,s)+`<div class="a-route-controls"><span></span>${btn('move','↑','','data-d="0,-1"')}<span></span>${btn('move','←','','data-d="-1,0"')}${btn('move','↓','','data-d="0,1"')}${btn('move','→','','data-d="1,0"')}</div>`;
 case 'program':return routeBoard(t,s)+`<p>重复单元：${s.commands.map(c=>({R:'→',D:'↓',L:'←',U:'↑'})[c]).join(' ')||'还没有安排'}</p><div class="a-controls">${[['R','→'],['D','↓'],['L','←'],['U','↑']].map(([v,l])=>btn('task',l,'small',`data-action="command" data-v="${v}"`)).join('')}</div><div class="a-controls">${btn('task','减少次数','small','data-action="repeat" data-v="-1"')}<span>重复 ${s.repeat} 次</span>${btn('task','增加次数','small','data-action="repeat" data-v="1"')}${btn('task','运行程序','primary','data-action="run"')}</div>`;
 case 'rhythm':return `<div class="a-reading">示范：${t.pattern.map(i=>esc(t.sounds[i])).join(' · ')}</div><p>你的输入：${s.order.map(i=>esc(t.sounds[i])).join(' · ')||'还没有输入'}</p><div class="a-controls">${btn('rhythmModel','▶ 听节奏示范','small')}${t.sounds.map((v,i)=>btn('tap',esc(v),'',`data-v="${i}"`)).join('')}${btn('task','撤销一拍','small','data-action="undo"')}</div>`;
 case 'debug':return `<div class="a-controls">${t.trials.map((r,i)=>btn('task',esc(r.label)+(s.observed.includes(i)?' ✓':''),'small',`data-action="observe" data-v="${i}"`)).join('')}</div><div class="a-choice-grid">${btn('task',(s.flags?.wall?'✓ ':'')+'先检查障碍','','data-action="flag" data-v="wall"')}${btn('task',(s.flags?.edge?'✓ ':'')+'先检查边界','','data-action="flag" data-v="edge"')}</div>${s.currentTrial!=null?`<div class="a-reading">测试：${esc(t.trials[s.currentTrial].label)}<br>${s.currentTrial===0?'正常前进一步':s.currentTrial===1?(s.flags?.wall?'拒绝穿过障碍 ✓':'错误：穿过了障碍'):(s.flags?.edge?'拒绝越过边界 ✓':'错误：走出了棋盘')}</div>`:''}`;
 case 'board':return board(t,s);
 default:return '<p>这项任务没有正确加载。</p>';
 }}
function routeBoard(t,s){return `<div class="a-board a-route-grid" style="--n:${t.width}" role="img" aria-label="路线格子">${Array.from({length:t.width*t.height},(_,i)=>{const x=i%t.width,y=Math.floor(i/t.width),wall=(t.walls||[]).some(p=>p[0]===x&&p[1]===y),goal=t.target[0]===x&&t.target[1]===y,here=s.position[0]===x&&s.position[1]===y;return `<div class="a-square ${wall?'wall':''} ${goal?'goal':''} ${s.path.some(p=>p[0]===x&&p[1]===y)?'visited':''}">${here?'🧭':wall?'🌳':goal?'🏁':t.via?.[0]===x&&t.via?.[1]===y?'⭐':'·'}</div>`;}).join('')}</div>`;}
function labVisual(t,i){const trial=t.trials[i];if(t.visual==='colors')return `<div class="a-token-row"><span class="a-token" style="width:90px;height:90px;background:${i?'#db9b55':'#8ca66f'}"></span></div><p>${esc(trial.note)}</p>`;if(t.visual==='wave')return `<svg viewBox="0 0 500 120" role="img" aria-label="振幅示意"><path d="M10 60Q60 ${60-trial.value*7} 110 60T210 60T310 60T410 60T490 60" fill="none" stroke="#6c987e" stroke-width="7"/></svg>`;if(t.visual==='chart')return `<div class="a-bars"><div><div class="a-barfill" style="height:${i?50:120}px"></div><small>100</small></div><div><div class="a-barfill" style="height:${i?100:126}px"></div><small>105</small></div></div><p class="a-lab-note">纵轴起点 ${i?95:0}；图示展示不同刻度的视觉差异，读数值再作比较。</p>`;return `<div class="a-bars"><div><div class="a-barfill" style="height:${Math.min(170,trial.value*18)}px"></div><small>${esc(trial.label)}：${trial.value}</small></div></div>`;}
function board(t,s){const chinese={R:'车',H:'马',E:'象',A:'士',K:'将',C:'炮',P:'兵'},pieceName=p=>p.type==='K'?(p.side==='r'?'帅':'将'):p.type==='P'?(p.side==='r'?'兵':'卒'):p.type==='E'?(p.side==='r'?'相':'象'):p.type==='A'?(p.side==='r'?'仕':'士'):chinese[p.type],size=t.size,rows=t.game==='xiangqi'?10:size;const cells=Array.from({length:size*rows},(_,i)=>{const x=i%size,y=Math.floor(i/size),p=t.game==='xiangqi'?B.at(s.pieces,x,y):null,value=s.board?.[i],candidate=t.mode==='mark'&&t.candidates.some(q=>q[0]===x&&q[1]===y),goal=t.target?.[0]===x&&t.target?.[1]===y;return `<button class="a-square ${x===0?'edge-left':''} ${x===size-1?'edge-right':''} ${y===0?'edge-top':''} ${y===rows-1?'edge-bottom':''} ${y===4?'river-top':''} ${y===5?'river-bottom':''} ${candidate||goal?'goal':''} ${s.marks.includes([x,y].join())?'marked':''}" data-a="board" data-x="${x}" data-y="${y}" aria-label="第${y+1}行第${x+1}列${p?' '+(p.side==='r'?'红':'黑')+pieceName(p):value?' '+(value===1?'黑子':'白子'):' 空点'}" ${t.mode==='mark'&&!candidate?'disabled':''}>${p?`<span class="a-piece ${p.side==='b'?'black':''} ${s.selected===p.id?'selected':''}">${pieceName(p)}</span>`:value?`<span class="a-stone ${value===2?'white':''}"></span>`:candidate?'◇':goal?'◎':`<span class="a-coord">${x+1},${y+1}</span>`}</button>`;}).join('');return `<p class="a-note">${t.game==='xiangqi'?(t.strict?'合法残局；规则检查包含自陷被将、九宫与将帅照面。':'象棋局部走法练习；不是完整对局。'):t.k===3?'儿童三连棋；不是五子棋规则。':['turn','align'].includes(t.goal)?'轮流或沿线准备游戏。':'局部棋形练习：儿童自由连五，不设禁手。'}${t.mode==='mark'?' 金色格是本题候选点。':''}</p><div class="a-board a-points ${t.game==='xiangqi'?'a-xiangqi':'a-gomoku'}" style="--n:${size}" role="group" aria-label="${t.game==='xiangqi'?'象棋练习盘':'连线棋盘'}">${t.game==='xiangqi'?'<svg class="a-palace-lines" viewBox="0 0 900 1000" preserveAspectRatio="none" aria-hidden="true"><path d="M350 50L550 250M550 50L350 250M350 750L550 950M550 750L350 950" fill="none" stroke="#a98b54" stroke-width="3"/></svg>':''}${cells}</div><div class="a-controls">${btn('task','撤销一步','small','data-action="undo"')}${t.goal==='win2'?btn('task','看对方回应','small','data-action="reply"'):''}</div>`;}

function token(x){return x.shape==='apple'?'<span class="emoji-token">🍎</span>':x.shape==='cookie'?'<span class="emoji-token">🍪</span>':x.shape==='cake'?'<span class="emoji-token">🥮</span>':`<span class="token ${x.color} ${x.shape}" aria-hidden="true"></span>`;}
function itemLabel(x){return x.shape==='apple'?'苹果':x.shape==='cookie'?'饼干':x.shape==='cake'?'派对点心':`${({red:'红色',blue:'蓝色',green:'绿色',gold:'金色'})[x.color]||''}${x.shape==='circle'?'圆片':x.shape==='triangle'?'三角片':'方片'}`;}
function itemButton(x){return `<button type="button" class="item-btn ${state.game.selected===x.id?'selected':''}" data-act="selectItem" data-id="${x.id}" aria-label="${itemLabel(x)} ${x.id}" aria-pressed="${state.game.selected===x.id}" ${state.game.checked?'disabled':''}>${token(x)}</button>`;}
function zoneName(z){return E.task(state.game).zoneLabels?.[z]||({left:'米米的盘子',middle:'小鸟的盘子',right:'点点的盘子',fourth:'小熊的盘子',red:'红色小屋',blue:'蓝色小屋',circle:'圆窗洞',square:'方窗洞'})[z]||z;}
function zoneIcon(z){const name=zoneName(z);return name.includes('米米')?'🐰':name.includes('点点')?'🦊':name.includes('小鸟')?'🐥':name.includes('小熊')?'🐻':z==='red'?'🔴':z==='blue'?'🔵':z==='match'?'🧺':z==='other'?'↗':'';}
function distributive(){
 const g=state.game,t=E.task(g),isShape=!!g.windows;
 const loose=g.items.filter(x=>isShape?!Object.values(g.windows).includes(x.id):!x.zone);
 return `<div class="items" aria-label="待放置的物品">${loose.map(itemButton).join('')||'<span class="muted">都送出去啦。还可以选中物品，再换一个位置。</span>'}</div><div class="drop-zones" style="--zones:${Math.min(t.zones.length,4)}">${t.zones.map(z=>{const assigned=g.items.filter(x=>isShape?g.windows[z]===x.id:x.zone===z);return `<div class="drop-zone ${g.selected?'target-active':''}" data-act="drop" data-zone="${z}"><button class="zone-hit" data-act="drop" data-zone="${z}">${isShape&&['circle','square'].includes(z)?`<span class="token green ${z}"></span> `:''}<span class="zone-avatar" aria-hidden="true">${zoneIcon(z)}</span>${zoneName(z)}${!isShape?' · '+assigned.length:''}</button><div class="items">${assigned.map(itemButton).join('')}</div></div>`;}).join('')}</div><p class="counter">先点物品，再点位置；也可以拖过去。分错了可以搬动，不会清空。</p>`;
}
function choiceButtons(options,english=false){return `<div class="choices ${english?'english-choices':''}">${options.map(([value,label,symbol])=>`<button type="button" class="choice ${state.game.choice===value?'chosen':''}" data-act="choose" data-value="${value}" aria-label="${esc(label)}" ${state.game.checked?'disabled':''}><span class="symbol">${Activities.picture(symbol)}</span><span class="label">${esc(label)}</span></button>`).join('')}</div>`;}
function tableGame(choice,english=false){return `<div class="table-game" role="group" aria-label="以桌面为参照放置小猫"><div class="table-top"></div><div class="table-leg left"></div><div class="table-leg right"></div>${['on','under'].map(pos=>`<button class="position-hit ${pos} ${choice===pos?'active':''}" data-act="${english?'enChoose':'choose'}" data-value="${pos}" aria-label="${pos==='on'?'on the table':'under the table'}">${choice===pos?'<span class="cat">🐈</span>':'<span class="muted">＋</span>'}${english?'':pos==='on'?'桌子上面':'桌子下面'}</button>`).join('')}</div>`;}
function patternTrain(t){const token=v=>Activities.picture(v==='circle'?'token:gold:circle':v==='square'?'token:green:square':v==='gold'?'🟡':v==='blue'?'🔵':'🔴');return `<div class="pattern-train">${t.sequence.map((v,i)=>`<span class="car">${i===0?'🚂 ':''}${v==='?'?(state.game.checked?token(state.game.choice):'？'):token(v)}</span>`).join('')}${t.gapIndex===undefined?`<span class="car ${t.wrongTail&&!state.game.checked?'wrong':''}">${state.game.checked?token(state.game.choice):t.wrongTail?token(t.wrongTail):'？'}</span>`:''}</div>`;}

window.ClassroomViews={academy(t,s,c,color){current=c;state={activity:s};palette=color||palette;return activityBody(t,s);},legacy(l,g){course=l;state={game:g};const t=E.task(g);if(['distribute','shape','assemble'].includes(t.kind))return (t.kind==='assemble'?Activities.assembly(t,g):'')+distributive();if(t.kind==='position')return tableGame(g.choice);if(t.kind==='pattern')return patternTrain(t)+choiceButtons(t.options);if(['route','sequence','counter','experiment'].includes(t.kind))return Activities.board(t,g);return choiceButtons(t.options);}};
})();